CREATE TABLE "plugin_wattanam_academic_management_class_registration_settings" ("id" TEXT PRIMARY KEY, "khmerNameMode" TEXT NOT NULL DEFAULT 'REQUIRED', "phoneMode" TEXT NOT NULL DEFAULT 'REQUIRED', "emailMode" TEXT NOT NULL DEFAULT 'REQUIRED', "photoMode" TEXT NOT NULL DEFAULT 'OPTIONAL', "passwordMode" TEXT NOT NULL DEFAULT 'REQUIRED', "sexMode" TEXT NOT NULL DEFAULT 'HIDDEN', "dateOfBirthMode" TEXT NOT NULL DEFAULT 'HIDDEN', "addressMode" TEXT NOT NULL DEFAULT 'HIDDEN', "generationMode" TEXT NOT NULL DEFAULT 'HIDDEN', "updatedAt" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);